            for _, r in ipairs(t.recipes) do trait:getFreeRecipes():add(r) end
            if BaseGameCharacterDetails and BaseGameCharacterDetails.SetTraitDescription then
                BaseGameCharacterDetails.SetTraitDescription(trait)
            end
            addedTrait = true
        end
    end
    if addedTrait and TraitFactory.sortList then TraitFactory.sortList() end
    for _, p in ipairs(KRjobsB41.PROFESSIONS) do
